input.script:
export const meta = {
  name: 'ams-wms-full-scan',
  description: 'Full directory scan + subsystem discovery for AMS (130 files) and WMS (257 files)',
  phases: ['AMS Scan', 'WMS Scan', 'Synthesis'],
}
const { targets } = args

// Phase 1: AMS and WMS file inventory (parallel)
phase('AMS Scan')
const amsFiles = await parallel(targets.filter(t => t.name === 'AMS').map(t => async () => {
  const { execSync } = require('child_process')

  // Full file enumeration
  const countOut = execSync(`find "${t.path}" -name "*.java" | wc -l`).toString().trim()
  const listOut = execSync(`find "${t.path}" -name "*.java" -exec wc -l {} + | sort -rn`).toString().trim()
  const namesOut = execSync(`find "${t.path}" -name "*.java" | sort`).toString().trim()

  // Main service class field extraction
  const amsMainFile = execSync(`ls "${t.path}"/ActivityManagerService.java 2>/dev/null && echo "EXISTS" || echo "NOTFOUND"`).toString().trim()

  return { name: t.name, count: countOut, files: listOut, names: namesOut.split('\n'), mainFile: amsMainFile }
}))

phase('WMS Scan')
const wmsFiles = await parallel(targets.filter(t => t.name === 'WMS').map(t => async () => {
  const { execSync } = require('child_process')

  // Full file enumeration
  const countOut = execSync(`find "${t.path}" -name "*.java" | wc -l`).toString().trim()
  const listOut = execSync(`find "${t.path}" -name "*.java" -exec wc -l {} + | sort -rn`).toString().trim()
  const namesOut = execSync(`find "${t.path}" -name "*.java" | sort`).toString().trim()

  // Main service class field extraction
  const wmsMainFile = execSync(`ls "${t.path}"/WindowManagerService.java 2>/dev/null && echo "EXISTS" || echo "NOTFOUND"`).toString().trim()

  return { name: t.name, count: countOut, files: listOut, names: namesOut.split('\n'), mainFile: wmsMainFile }
}))

phase('Synthesis')
log(`AMS: ${amsFiles[0].count} files, main: ${amsFiles[0].mainFile}`)
log(`WMS: ${wmsFiles[0].count} files, main: ${wmsFiles[0].mainFile}`)

return { ams: amsFiles[0], wms: wmsFiles[0] }

